import { ImageResponse } from "next/og";
import { metrics, profile } from "@/content/profile";

export const alt = `${profile.name}, ${profile.role}`;
export const size = { width: 1200, height: 630 };
export const contentType = "image/png";

const MARKHOR = "data:image/svg+xml;base64,";

export default function OpengraphImage() {
  return new ImageResponse(
    (
      <div style={{ width: "100%", height: "100%", display: "flex", background: "#05070b", color: "#edf2f8", padding: "64px 72px", fontFamily: "sans-serif", position: "relative" }}>
        <div style={{ position: "absolute", top: -200, right: -150, width: 700, height: 700, borderRadius: 700, background: "radial-gradient(circle, rgba(61,139,255,0.28), rgba(5,7,11,0) 70%)", display: "flex" }} />
        <div style={{ display: "flex", flexDirection: "column", flex: 1, justifyContent: "space-between" }}>
          <div style={{ display: "flex", flexDirection: "column" }}>
            <div style={{ fontSize: 21, letterSpacing: 3, color: "#8ccbff", textTransform: "uppercase", display: "flex" }}>{profile.role} · {profile.secondaryRole}</div>
            <div style={{ fontSize: 72, fontWeight: 700, lineHeight: 1.05, marginTop: 22, letterSpacing: -2, display: "flex", maxWidth: 760 }}>{profile.name}</div>
            <div style={{ fontSize: 34, color: "#8794a8", marginTop: 18, display: "flex" }}>I ship AI agents into the real world.</div>
          </div>
          <div style={{ display: "flex", gap: 18 }}>
            {metrics.map((m) => (
              <div key={m.label} style={{ display: "flex", flexDirection: "column", border: "1px solid #263043", borderRadius: 18, padding: "16px 22px", background: "#0a0e15" }}>
                <div style={{ fontSize: 40, fontWeight: 700, display: "flex" }}>{`${m.value}${m.suffix}`}</div>
                <div style={{ fontSize: 18, color: "#8794a8", display: "flex" }}>{m.label}</div>
              </div>
            ))}
          </div>
          <div style={{ fontSize: 22, color: "#8794a8", display: "flex" }}>Founder, {profile.company} · {profile.location}</div>
        </div>
        <img src={MARKHOR} width={230} height={313} style={{ position: "absolute", right: 70, top: 48 }} />
      </div>
    ),
    size,
  );
}
